import{_ as a,o,c as t,a5 as r}from"./chunks/framework.DOB-AMqW.js";const m=JSON.parse('{"title":"AR Tamil Jathagam Privacy Policy","description":"Official Privacy Policy for AR Tamil Jathagam.","frontmatter":{"title":"AR Tamil Jathagam Privacy Policy","description":"Official Privacy Policy for AR Tamil Jathagam.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"privacy/ar-tamil-jathagam.md","filePath":"privacy/ar-tamil-jathagam.md"}'),i={name:"privacy/ar-tamil-jathagam.md"};function n(s,e,l,c,d,p){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="privacy-policy-for-ar-tamil-jathagam" tabindex="-1">Privacy Policy for AR Tamil Jathagam <a class="header-anchor" href="#privacy-policy-for-ar-tamil-jathagam" aria-label="Permalink to &quot;Privacy Policy for AR Tamil Jathagam&quot;">​</a></h1><p><strong>Effective Date:</strong> August 1, 2026<br><strong>Last Updated:</strong> August 1, 2026</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>AR Tamil Jathagam is an astrology application developed by <strong>Anand Raja</strong>. It creates horoscope, Panchanga, compatibility, transit, Kundali, and Chinese astrology information from details you provide.</p><p>The app has no advertising or developer-operated analytics. It does not create a general-purpose developer cloud account.</p><h2 id="birth-and-profile-information" tabindex="-1">Birth and Profile Information <a class="header-anchor" href="#birth-and-profile-information" aria-label="Permalink to &quot;Birth and Profile Information&quot;">​</a></h2><p>Depending on the feature, the app can process a person&#39;s name, parents&#39; names, gender, birth date and time, birthplace, latitude, longitude, time-zone offset, and optional sunrise setting. Couple-matching features can process details for two people. Horoscope calculations can derive astrological charts, planetary positions, Nakshatra, Rasi, Dasha periods, Dosham, compatibility results, predictions, and related interpretations.</p><p>Most astrology calculations run on your device. Do not enter another person&#39;s information unless you have permission to use it.</p><h2 id="local-storage" tabindex="-1">Local Storage <a class="header-anchor" href="#local-storage" aria-label="Permalink to &quot;Local Storage&quot;">​</a></h2><p>You can save up to ten birth profiles on the device. Saved profiles include their label, birth details, and save time and are stored as plain JSON in localStorage; they are not encrypted. The app also stores language preference, a local login session, an optional data-cipher key, and administrator-configured author or PDF preferences.</p><p>The login compares SHA-1 password hashes locally. This is an interface access gate, not an online account or strong protection for locally stored profiles. Secure the device with Android encryption and a screen lock.</p><h2 id="google-sheets-and-clipboard-export" tabindex="-1">Google Sheets and Clipboard Export <a class="header-anchor" href="#google-sheets-and-clipboard-export" aria-label="Permalink to &quot;Google Sheets and Clipboard Export&quot;">​</a></h2><p>The app can fetch saved profile rows from a configured published Google Sheet. A row contains an identifier, label, transformed birth-data string, and save time. You can also copy a transformed row to the clipboard for manual pasting into a sheet.</p><p>The transformation uses a custom reversible substitution cipher. It is obfuscation and should not be treated as modern, strong encryption. Its secret key is stored in localStorage. Labels and row metadata are not hidden by that transformation.</p><p>Google receives the sheet identifier and standard connection information such as IP address, user agent, request time, and requested resource. The sheet owner controls the source records. Google&#39;s processing is governed by the <a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">Google Privacy Policy</a>. Clipboard contents may be visible to the operating system and other permitted apps.</p><h2 id="online-panchanga-services" tabindex="-1">Online Panchanga Services <a class="header-anchor" href="#online-panchanga-services" aria-label="Permalink to &quot;Online Panchanga Services&quot;">​</a></h2><p>When online Panchanga information is requested, the app sends a selected date and geographic coordinates to sunrise-sunset.org, SunriseSunset.io, and the Norwegian Meteorological Institute. It sends date, time, place name, coordinates, and time-zone offset to VedAstro for detailed calculations. These providers also receive standard connection metadata and apply their own privacy policies.</p><p>The app does not request the device&#39;s GPS location. Coordinates come from the place selected or entered in the app.</p><h2 id="pdf-and-image-exports" tabindex="-1">PDF and Image Exports <a class="header-anchor" href="#pdf-and-image-exports" aria-label="Permalink to &quot;PDF and Image Exports&quot;">​</a></h2><p>The app can create horoscope, compatibility, Kundali, Chinese astrology, and other reports as PDF, and can download a Panchanga timeline image. Reports may contain names, birth details, charts, interpretations, author information, or passwords applied to a PDF. Saved, downloaded, printed, or shared files are readable by the destination subject to any PDF protection you selected.</p><h2 id="information-received-by-the-developer" tabindex="-1">Information Received by the Developer <a class="header-anchor" href="#information-received-by-the-developer" aria-label="Permalink to &quot;Information Received by the Developer&quot;">​</a></h2><p>The developer does not automatically receive locally stored profiles, login passwords, cipher keys, calculations, or exported reports. The owner of the configured Google Sheet can access its rows. External Panchanga providers receive the request information described above. If you contact support, the developer receives what you choose to send.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>The app uses internet access for optional online Panchanga and Google Sheet features and uses browser or Android file, print, clipboard, or sharing capabilities after your action. The reviewed source does not request location, contacts, phone, SMS, call-log, camera, or microphone access.</p><h2 id="retention-and-deletion" tabindex="-1">Retention and Deletion <a class="header-anchor" href="#retention-and-deletion" aria-label="Permalink to &quot;Retention and Deletion&quot;">​</a></h2><p>Local profiles can be removed from the saved-user interface. To remove all local records, clear app storage or uninstall the Android app; in a browser, clear the site&#39;s storage and cache. This does not delete Google Sheet rows, clipboard history, or exported files. Delete those through the relevant Google account, sheet owner, operating-system controls, and every file destination.</p><h2 id="astrology-disclaimer" tabindex="-1">Astrology Disclaimer <a class="header-anchor" href="#astrology-disclaimer" aria-label="Permalink to &quot;Astrology Disclaimer&quot;">​</a></h2><p>Astrological results are provided for cultural, educational, and entertainment purposes. They are not scientific findings or substitutes for medical, legal, financial, relationship, or other professional advice.</p><h2 id="changes-and-contact" tabindex="-1">Changes and Contact <a class="header-anchor" href="#changes-and-contact" aria-label="Permalink to &quot;Changes and Contact&quot;">​</a></h2><p>This policy may be updated when features or data practices change.</p><ul><li><strong>Developer:</strong> Anand Raja</li><li><strong>Email:</strong> <a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></li></ul>',31)])])}const f=a(i,[["render",n]]);export{m as __pageData,f as default};
